    cols = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    axis_row = next((r for r, cs in rows.items() if len(cs) >= 2), None)
    if axis_row is not None:
        cs = rows[axis_row]
        for c in range(min(cs), max(cs) + 1):
            if out[axis_row][c] == 0:
                out[axis_row][c] = 3
        for r, c in points:
            if r != axis_row:
                for rr in range(min(r, axis_row), max(r, axis_row) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
        return out
    axis_col = next((c for c, rs in cols.items() if len(rs) >= 2), None)
    if axis_col is not None:
        rs = cols[axis_col]
        for r in range(min(rs), max(rs) + 1):
            if out[r][axis_col] == 0:
                out[r][axis_col] = 3
        for r, c in points:
            if c != axis_col:
                for cc in range(min(c, axis_col), max(c, axis_col) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
